/**
 * cours-fiches-azure.mjs — KJEMO-AZURE-COURS-01 · KJEMO IT Toolkit
 * ---------------------------------------------------------------------------
 * Fiches Azure tirées du cours « Infonuagique » : groupes de ressources,
 * verrous et rôles, réseau virtuel (VNet), sous-réseaux, adresses IP, machine
 * virtuelle, DNS public et privé, peering, routes, points de terminaison de
 * service et privés, enfin Azure Load Balancer.
 *
 * Rédigées à la main, dans nos mots, en Azure CLI (`az`) : ni les
 * diapositives ni les énoncés ne sont republiés. Ce qui existait déjà au
 * catalogue n'est pas refait : les ASSISTANTS Azure lisent et diagnostiquent
 * (abonnement, RBAC, réseaux, DNS, interfaces, stockage). Ces fiches
 * CONSTRUISENT ; lorsqu'un assistant lit la même chose, la fiche le prolonge
 * (champ `assistant`). Aucun mot de passe ni aucune clé ne figure dans une
 * fiche, et le Toolkit n'exécute jamais rien.
 */
import { V_COURS, lec, mod, itr, sh } from './cours-outils.mjs';

const DOC = (chemin) => `https://learn.microsoft.com/${chemin}`;
