const PRIV_GROUPE = 'Azure CLI connectée (`az login`, faite par toi) ; rôle Contributeur sur le groupe de ressources visé.';

const REGIONS = ['canadacentral', 'canadaeast', 'eastus', 'eastus2', 'centralus', 'westus2', 'northeurope', 'westeurope', 'francecentral', 'uksouth'];
const GROUPE = { id: 'groupe', label: 'groupe de ressources', type: 'nomAzure', exemple: 'rg-lab', aide: 'Le nom du groupe de ressources (lettres, chiffres, tirets). Il sert de dossier à toutes les ressources du laboratoire.' };
const REGION = { id: 'region', label: 'région Azure', type: 'choix', choix: REGIONS, exemple: 'canadacentral', aide: 'Le nom technique de la région (canadacentral = Canada Centre). « az account list-locations » donne la liste complète.' };
