const COMPTE = { id: 'compte', label: 'compte de stockage', type: 'compteStockage', exemple: 'stlab01', aide: 'Le nom du compte de stockage : 3 à 24 caractères, minuscules et chiffres seulement. Il doit être unique dans tout Azure.' };
