/** Fiche Azure (une seule méthode « azure », commandes `az`). */
function ficheAz({ id, titre, resume, effet, intentions, motsCles, params = [], privileges = PRIV_GROUPE, prerequis = [], etapes, verification, retour = null, depannage = null, sources, figures = [], rappel = null, assistant = null }) {
  return {
    id,
    titre,
    categorie: CATEGORIE,
    resume,
    effet,
    intentions,
    motsCles,
    params,
    ...(prerequis.length ? { prerequis } : {}),
    methodes: [{ id: 'azure', privileges, etapes, verification, retour, ...(depannage ? { depannage } : {}) }],
    assistant,
    sources,
    validation: V_AZ,
    origine: 'cours',
    ...(figures.length ? { figures } : {}),
    ...(rappel ? { rappel } : {}),
  };
}

